package android.app; import android.content.Intent; import android.os.IBinder; import java.io.File; public class Service { public static final int START_NOT_STICKY=2,START_STICKY=1; public int foregroundCount; private final File base=new File(System.getProperty("java.io.tmpdir"),"foreground-harness-"+System.nanoTime()); public void onCreate(){} public void onDestroy(){} public int onStartCommand(Intent i,int f,int s){return 0;} public IBinder onBind(Intent i){return null;} public void startForeground(int id,Notification n){foregroundCount++;} public void stopForeground(boolean b){} public boolean stopSelfResult(int id){return true;} public File getFilesDir(){File f=new File(base,"files");f.mkdirs();return f;} public <T> T getSystemService(Class<T> c){try{return c.getDeclaredConstructor().newInstance();}catch(Exception e){throw new RuntimeException(e);}} public ApplicationInfo getApplicationInfo(){return new ApplicationInfo();} public static class ApplicationInfo {public String nativeLibraryDir="/unused";} }
